public class CelestialScribe {
    private final StarlightListener listener;

    private CelestialScribe() {
        this.listener = new StarlightListener() {
            @Override
            public void onCosmicEvent(CosmicEvent event) {
                recordTwinkle();
            }
        };
    }

    public static CelestialScribe scribeInstance(CosmicSource source) {
        CelestialScribe scribe = new CelestialScribe();
        source.registerListener(scribe.listener);
        return scribe;
    }

    public void recordTwinkle() {
        System.out.println("Twinkle recorded by " + Thread.currentThread().getName());
    }

    interface CosmicSource {
        void registerListener(StarlightListener listener);
    }

    interface StarlightListener {
        void onCosmicEvent(CosmicEvent event);
    }

    interface CosmicEvent {
    }

    static class SimpleCosmicSource implements CosmicSource {
        private StarlightListener listener;

        @Override
        public synchronized void registerListener(StarlightListener listener) {
            this.listener = listener;
        }

        synchronized void fireEvent() {
            if (listener != null) {
                listener.onCosmicEvent(new CosmicEvent() {
                });
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
        SimpleCosmicSource source = new SimpleCosmicSource();
        scribeInstance(source);

        Thread eventThread = new Thread(source::fireEvent, "event-thread");
        eventThread.start();
        eventThread.join();
    }
}

