public class SafeMutableInteger {
    private int value;

    public SafeMutableInteger(int value) {
        this.value = value;
    }

    public synchronized int getValue() {
        return value;
    }

    public synchronized void setValue(int value) {
        this.value = value;
    }

    public static void main(String[] args) throws InterruptedException {
        SafeMutableInteger holder = new SafeMutableInteger(0);

        Runnable incrementer = () -> {
            for (int i = 0; i < 1000; i++) {
                holder.setValue(holder.getValue() + 1);
            }
        };

        Runnable reader = () -> {
            for (int i = 0; i < 1000; i++) {
                int v = holder.getValue();
            }
        };

        Thread t1 = new Thread(incrementer, "writer-thread");
        Thread t2 = new Thread(reader, "reader-thread");

        t1.start();
        t2.start();
        t1.join();
        t2.join();

        System.out.println("Final value: " + holder.getValue());
    }
}

public class CountingSheep {
    private volatile boolean asleep = false;

    public void tryToSleep() {
        while (!asleep) {
            countSomeSheep();
        }
    }

    public void countSomeSheep() {
        // counting sheep
    }

    public void wakeToSleep() {
        asleep = true;
    }

    public static void main(String[] args) throws InterruptedException {
        CountingSheep person = new CountingSheep();

        Thread sleeper = new Thread(person::tryToSleep, "sleeper-thread");
        sleeper.start();

        Thread.sleep(100);
        person.wakeToSleep();

        sleeper.join();
        System.out.println("Fell asleep.");
    }
}

