import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;

public class ArkLoader {

    enum Species {
        LION, TIGER, ELEPHANT, ZEBRA
    }

    enum Gender {
        MALE, FEMALE
    }

    static class Animal {
        private final Species species;
        private final Gender gender;

        Animal(Species species, Gender gender) {
            this.species = species;
            this.gender = gender;
        }

        Species getSpecies() {
            return species;
        }

        Gender getGender() {
            return gender;
        }

        @Override
        public String toString() {
            return species + "-" + gender;
        }
    }

    static class AnimalPair {
        private final Animal first;
        private final Animal second;

        AnimalPair(Animal first, Animal second) {
            this.first = first;
            this.second = second;
        }

        @Override
        public String toString() {
            return "[" + first + ", " + second + "]";
        }
    }

    static class Ark {
        private final List<AnimalPair> pairs = new ArrayList<AnimalPair>();

        synchronized void addPair(AnimalPair pair) {
            pairs.add(pair);
        }

        synchronized int size() {
            return pairs.size();
        }
    }

    static class SpeciesGenderComparator implements Comparator<Animal> {
        @Override
        public int compare(Animal a1, Animal a2) {
            int speciesCompare = a1.getSpecies().compareTo(a2.getSpecies());
            if (speciesCompare != 0) {
                return speciesCompare;
            }
            return a1.getGender().compareTo(a2.getGender());
        }
    }

    int loadTheArk(Collection<Animal> candidates) {
        // All variables below are local to this method invocation and are
        // therefore confined to the calling thread; no shared mutable state
        // escapes this method.
        List<Animal> sorted = new ArrayList<Animal>(candidates);
        Collections.sort(sorted, new SpeciesGenderComparator());

        Ark ark = new Ark();
        int pairCount = 0;

        int i = 0;
        while (i < sorted.size() - 1) {
            Animal a = sorted.get(i);
            Animal b = sorted.get(i + 1);
            if (a.getSpecies() == b.getSpecies() && a.getGender() != b.getGender()) {
                ark.addPair(new AnimalPair(a, b));
                pairCount++;
                i += 2;
            } else {
                i++;
            }
        }

        return pairCount;
    }

    public static void main(String[] args) throws InterruptedException {
        final List<Animal> candidates = new ArrayList<Animal>();
        candidates.add(new Animal(Species.LION, Gender.MALE));
        candidates.add(new Animal(Species.LION, Gender.FEMALE));
        candidates.add(new Animal(Species.TIGER, Gender.MALE));
        candidates.add(new Animal(Species.TIGER, Gender.FEMALE));
        candidates.add(new Animal(Species.ZEBRA, Gender.MALE));

        final ArkLoader loader = new ArkLoader();
        final int[] result = new int[1];

        Thread loadingThread = new Thread(() -> {
            result[0] = loader.loadTheArk(candidates);
        }, "ark-loading-thread");

        loadingThread.start();
        loadingThread.join();

        System.out.println("Pairs loaded: " + result[0]);
    }
}

