import java.math.BigInteger;
import java.util.Arrays;

public class FactorCache {

    static final class OneValueCache {
        private final BigInteger lastNumber;
        private final BigInteger[] lastFactors;

        OneValueCache(BigInteger i, BigInteger[] factors) {
            lastNumber = i;
            lastFactors = Arrays.copyOf(factors, factors.length);
        }

        BigInteger[] getFactors(BigInteger i) {
            if (lastNumber == null || !lastNumber.equals(i)) {
                return null;
            }
            return Arrays.copyOf(lastFactors, lastFactors.length);
        }
    }

    public static void main(String[] args) throws InterruptedException {
        BigInteger number = BigInteger.valueOf(60);
        BigInteger[] factors = { BigInteger.valueOf(2), BigInteger.valueOf(2),
                BigInteger.valueOf(3), BigInteger.valueOf(5) };

        final OneValueCache cache = new OneValueCache(number, factors);

        Thread reader = new Thread(() -> {
            BigInteger[] cached = cache.getFactors(BigInteger.valueOf(60));
            System.out.println("Cached factors: " + Arrays.toString(cached));
        }, "cache-reader-thread");

        reader.start();
        reader.join();
    }
}

import java.math.BigInteger;
import java.util.Arrays;

public class CachingServlet {

    static final class OneValueCache {
        private final BigInteger lastNumber;
        private final BigInteger[] lastFactors;

        OneValueCache(BigInteger i, BigInteger[] factors) {
            lastNumber = i;
            lastFactors = Arrays.copyOf(factors, factors.length);
        }

        BigInteger[] getFactors(BigInteger i) {
            if (lastNumber == null || !lastNumber.equals(i)) {
                return null;
            }
            return Arrays.copyOf(lastFactors, lastFactors.length);
        }
    }

    private volatile OneValueCache cache = new OneValueCache(null, new BigInteger[0]);

    public BigInteger[] handleRequest(BigInteger value) {
        BigInteger[] factors = cache.getFactors(value);
        if (factors == null) {
            factors = compute(value);
            cache = new OneValueCache(value, factors);
        }
        return factors;
    }

    private BigInteger[] compute(BigInteger value) {
        return new BigInteger[] { value };
    }

    public static void main(String[] args) throws InterruptedException {
        final CachingServlet servlet = new CachingServlet();

        Runnable request = () -> {
            BigInteger[] result = servlet.handleRequest(BigInteger.valueOf(42));
            System.out.println(Thread.currentThread().getName() + " -> " + Arrays.toString(result));
        };

        Thread t1 = new Thread(request, "request-thread-1");
        Thread t2 = new Thread(request, "request-thread-2");

        t1.start();
        t2.start();
        t1.join();
        t2.join();
    }
}

