public class PrivateLockWidget {

    static class Widget {
        private int value;

        Widget(int value) {
            this.value = value;
        }

        int getValue() {
            return value;
        }

        void setValue(int value) {
            this.value = value;
        }
    }

    private final Object lock = new Object();
    private Widget widget = new Widget(0);

    public void updateWidget(int newValue) {
        synchronized (lock) {
            widget.setValue(newValue);
        }
    }

    public int readWidgetValue() {
        synchronized (lock) {
            return widget.getValue();
        }
    }

    public static void main(String[] args) throws InterruptedException {
        final PrivateLockWidget holder = new PrivateLockWidget();

        Thread writer = new Thread(() -> {
            for (int i = 0; i < 100; i++) {
                holder.updateWidget(i);
            }
        }, "writer-thread");

        Thread reader = new Thread(() -> {
            for (int i = 0; i < 100; i++) {
                holder.readWidgetValue();
            }
        }, "reader-thread");

        writer.start();
        reader.start();
        writer.join();
        reader.join();

        System.out.println("Final widget value: " + holder.readWidgetValue());
    }
}

