            reader.start();
        }
        for (Thread reader : readers) {
            reader.join();
        }
    }
}

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class DelegatingVehicleTracker {

    static class Point {
        public final int x;
        public final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public String toString() {
            return "(" + x + ", " + y + ")";
        }
    }

    private final ConcurrentHashMap<String, Point> locations;

    public DelegatingVehicleTracker(Map<String, Point> initialLocations) {
        this.locations = new ConcurrentHashMap<String, Point>(initialLocations);
    }

    public Map<String, Point> getLocations() {
        return Collections.unmodifiableMap(locations);
    }

    public Point getLocation(String id) {
        return locations.get(id);
    }

    public void setLocation(String id, int x, int y) {
        if (locations.replace(id, new Point(x, y)) == null) {
            throw new IllegalArgumentException("No such vehicle: " + id);
        }
    }

    public Map<String, Point> getLocationsAsStatic() {
        return Collections.unmodifiableMap(new HashMap<String, Point>(locations));
    }

    public static void main(String[] args) throws InterruptedException {
        Map<String, Point> initial = new HashMap<String, Point>();
        initial.put("car1", new Point(0, 0));
        initial.put("car2", new Point(1, 1));

        final DelegatingVehicleTracker tracker = new DelegatingVehicleTracker(initial);

        Thread updater1 = new Thread(() -> tracker.setLocation("car1", 5, 5), "updater-1");
        Thread updater2 = new Thread(() -> tracker.setLocation("car2", 9, 9), "updater-2");

        updater1.start();
        updater2.start();
        updater1.join();
        updater2.join();

        System.out.println("Live view: " + tracker.getLocations());
        System.out.println("Static snapshot: " + tracker.getLocationsAsStatic());
        System.out.println("car1 location: " + tracker.getLocation("car1"));
    }
}

