import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class PublishingVehicleTracker {

    static class SafePoint {
        private final int x;
        private final int y;

        SafePoint(int x, int y) {
            this.x = x;
            this.y = y;
        }

        int getX() {
            return x;
        }

        int getY() {
            return y;
        }

        @Override
        public String toString() {
            return "(" + x + ", " + y + ")";
        }
    }

    private final Map<String, SafePoint> locations;
    private final Map<String, SafePoint> unmodifiableLocations;

    public PublishingVehicleTracker(Map<String, SafePoint> initialLocations) {
        this.locations = new ConcurrentHashMap<String, SafePoint>(initialLocations);
        this.unmodifiableLocations = Collections.unmodifiableMap(locations);
    }

    public Map<String, SafePoint> getLocations() {
        return unmodifiableLocations;
    }

    public SafePoint getLocation(String id) {
        return locations.get(id);
    }

    public void setLocation(String id, int x, int y) {
        if (!locations.containsKey(id)) {
            throw new IllegalArgumentException("No such vehicle: " + id);
        }
        locations.put(id, new SafePoint(x, y));
    }

    public static void main(String[] args) throws InterruptedException {
        Map<String, SafePoint> initial = new HashMap<String, SafePoint>();
        initial.put("car1", new SafePoint(0, 0));
        initial.put("car2", new SafePoint(2, 2));

        final PublishingVehicleTracker tracker = new PublishingVehicleTracker(initial);

        Thread updater = new Thread(() -> tracker.setLocation("car1", 10, 10), "updater-thread");
        updater.start();
        updater.join();

        System.out.println("Locations: " + tracker.getLocations());
        System.out.println("car1: " + tracker.getLocation("car1"));
    }
}

import java.util.ArrayList;
import java.util.Collection;
import java.util.Iterator;
import java.util.List;
import java.util.ListIterator;

/**
 * A List decorator that adds a thread-safe putIfAbsent operation by
 * composing an underlying List instance. All mutative operations are
 * synchronized on this instance to keep the composed putIfAbsent
 * check-then-act sequence atomic.
 */
public class ImproveList<E> implements List<E> {
    private final List<E> list;

    public ImproveList(List<E> list) {
        this.list = list;
    }

    public synchronized boolean putIfAbsent(E element) {
        boolean absent = !list.contains(element);
        if (absent) {
            list.add(element);
        }
        return absent;
    }

    @Override
    public int size() {
        return list.size();
    }

    @Override
    public boolean isEmpty() {
        return list.isEmpty();
    }

    @Override
    public boolean contains(Object o) {
        return list.contains(o);
    }

    @Override
    public Iterator<E> iterator() {
        return list.iterator();
    }

    @Override
    public Object[] toArray() {
        return list.toArray();
    }

    @Override
    public <T> T[] toArray(T[] a) {
        return list.toArray(a);
    }

    @Override
    public synchronized boolean add(E e) {
        return list.add(e);
    }

    @Override
    public synchronized boolean remove(Object o) {
        return list.remove(o);
    }

    @Override
    public boolean containsAll(Collection<?> c) {
        return list.containsAll(c);
    }

    @Override
    public synchronized boolean addAll(Collection<? extends E> c) {
        return list.addAll(c);
    }

    @Override
    public synchronized boolean addAll(int index, Collection<? extends E> c) {
        return list.addAll(index, c);
    }

    @Override
    public synchronized boolean removeAll(Collection<?> c) {
        return list.removeAll(c);
    }

    @Override
    public synchronized boolean retainAll(Collection<?> c) {
        return list.retainAll(c);
    }

    @Override
    public synchronized void clear() {
        list.clear();
    }

    @Override
    public E get(int index) {
        return list.get(index);
    }

    @Override
    public synchronized E set(int index, E element) {
        return list.set(index, element);
    }

    @Override
    public synchronized void add(int index, E element) {
        list.add(index, element);
    }

    @Override
    public synchronized E remove(int index) {
        return list.remove(index);
    }

    @Override
    public int indexOf(Object o) {
        return list.indexOf(o);
    }

    @Override
    public int lastIndexOf(Object o) {
        return list.lastIndexOf(o);
    }

    @Override
    public ListIterator<E> listIterator() {
        return list.listIterator();
    }

    @Override
    public ListIterator<E> listIterator(int index) {
        return list.listIterator(index);
    }

    @Override
    public List<E> subList(int fromIndex, int toIndex) {
        return list.subList(fromIndex, toIndex);
    }

    public static void main(String[] args) throws InterruptedException {
        final ImproveList<String> improveList = new ImproveList<String>(new ArrayList<String>());

        Runnable task = () -> {
            boolean added = improveList.putIfAbsent("apple");
            System.out.println(Thread.currentThread().getName() + " added apple: " + added);
        };

        Thread t1 = new Thread(task, "thread-1");
        Thread t2 = new Thread(task, "thread-2");

        t1.start();
        t2.start();
        t1.join();
        t2.join();

        System.out.println("Final list: " + improveList);
    }

    @Override
    public String toString() {
        return list.toString();
    }
}

import java.util.concurrent.CountDownLatch;

public class TimingHarness {

    public static long timeTasks(int nThreads, final Runnable task) throws InterruptedException {
        final CountDownLatch startGate = new CountDownLatch(1);
        final CountDownLatch endGate = new CountDownLatch(nThreads);

        for (int i = 0; i < nThreads; i++) {
            Thread t = new Thread(() -> {
                try {
                    startGate.await();
                    try {
                        task.run();
                    } finally {
                        endGate.countDown();
                    }
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                }
            });
            t.start();
        }

        long start = System.nanoTime();
        startGate.countDown();
        endGate.await();
        long end = System.nanoTime();

        return end - start;
    }

    public static void main(String[] args) throws InterruptedException {
        Runnable sampleTask = () -> {
            long sum = 0;
            for (int i = 0; i < 1_000_000; i++) {
                sum += i;
            }
        };

        long elapsedNanos = timeTasks(1, sampleTask);
        System.out.println("Elapsed time (ns): " + elapsedNanos);
    }
}

import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.FutureTask;

public class Preloader {

    interface ProductInfo {
    }

    static class DataLoadException extends Exception {
        DataLoadException(String message) {
            super(message);
        }

        DataLoadException(String message, Throwable cause) {
            super(message, cause);
        }
    }

    private final FutureTask<ProductInfo> future = new FutureTask<ProductInfo>(new Callable<ProductInfo>() {
        @Override
        public ProductInfo call() throws DataLoadException {
            return loadProductInfo();
        }
    });

    private final Thread thread = new Thread(future, "preload-thread");

    public void start() {
        thread.start();
    }

    public ProductInfo get() throws DataLoadException, InterruptedException {
        try {
            return future.get();
        } catch (ExecutionException e) {
            Throwable cause = e.getCause();
            if (cause instanceof DataLoadException) {
                throw (DataLoadException) cause;
            } else if (cause instanceof RuntimeException) {
                throw (RuntimeException) cause;
            } else {
                throw launderThrowable(cause);
            }
        }
    }

    private RuntimeException launderThrowable(Throwable t) {
        if (t instanceof RuntimeException) {
            return (RuntimeException) t;
        } else if (t instanceof Error) {
            throw (Error) t;
        } else {
            throw new IllegalStateException("Unchecked exception", t);
        }
    }

    static ProductInfo loadProductInfo() throws DataLoadException {
        ProductInfo info = new ProductInfo() {
            @Override
            public String toString() {
                return "ProductInfo{loaded=true}";
            }
        };
        return info;
    }

    public static void main(String[] args) throws Exception {
        Preloader preloader = new Preloader();
        preloader.start();

        ProductInfo info = preloader.get();
        System.out.println("Loaded: " + info);
    }
}

import java.math.BigInteger;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class PrimeGenerator implements Runnable {
    private final List<BigInteger> primes = Collections.synchronizedList(new ArrayList<BigInteger>());
    private volatile boolean cancelled = false;

    @Override
    public void run() {
        BigInteger p = BigInteger.ONE;
        while (!cancelled) {
            p = p.nextProbablePrime();
            synchronized (this) {
                primes.add(p);
            }
        }
    }

    public void cancel() {
        cancelled = true;
    }

    public List<BigInteger> getPrimes() {
        synchronized (this) {
            return new ArrayList<BigInteger>(primes);
        }
    }

    public static void main(String[] args) throws InterruptedException {
        PrimeGenerator generator = new PrimeGenerator();
        ExecutorService executor = Executors.newFixedThreadPool(1);

        executor.execute(generator);
        try {
            Thread.sleep(1000);
        } finally {
            generator.cancel();
        }

        executor.shutdown();

        List<BigInteger> primes = generator.getPrimes();
        System.out.println("Found " + primes.size() + " primes.");
    }
}

