import java.math.BigInteger;
import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.BlockingQueue;

public class PrimeProducerConsumer {

    static class PrimeProducer extends Thread {
        private final BlockingQueue<BigInteger> queue;
        private final int count;

        PrimeProducer(BlockingQueue<BigInteger> queue, int count) {
            this.queue = queue;
            this.count = count;
        }

        @Override
        public void run() {
            try {
                BigInteger p = BigInteger.ONE;
                int produced = 0;
                while (!Thread.currentThread().isInterrupted() && produced < count) {
                    p = p.nextProbablePrime();
                    queue.put(p);
                    produced++;
                }
            } catch (InterruptedException consumed) {
                Thread.currentThread().interrupt();
            }
        }

        void cancel() {
            interrupt();
        }
    }

    static void consume(BlockingQueue<BigInteger> queue, int count) throws InterruptedException {
        for (int i = 0; i < count; i++) {
            BigInteger prime = queue.take();
            System.out.println("Consumed: " + prime);
        }
    }

    public static void main(String[] args) throws InterruptedException {
        final int primeCount = 10;
        BlockingQueue<BigInteger> queue = new ArrayBlockingQueue<BigInteger>(5);

        PrimeProducer producer = new PrimeProducer(queue, primeCount);
        Thread consumerThread = new Thread(() -> {
            try {
                consume(queue, primeCount);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }, "consumer-thread");

        producer.start();
        consumerThread.start();

        consumerThread.join();
        producer.cancel();
        producer.join();

        System.out.println("Done.");
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class ParallelProcessing {

    interface Element {
        void process();
    }

    interface Node {
        Node getChild(int i);

        int getChildCount();

        void compute();
    }

    static void processSequentially(List<Element> elements) {
        for (Element e : elements) {
            e.process();
        }
    }

    static void processInParallel(ExecutorService exec, List<Element> elements) throws InterruptedException {
        final CountDownLatch latch = new CountDownLatch(elements.size());
        for (final Element e : elements) {
            exec.execute(() -> {
                try {
                    e.process();
                } finally {
                    latch.countDown();
                }
            });
        }
        latch.await();
    }

    static void processSequentially(Node root, List<Node> results) {
        if (root == null) {
            return;
        }
        root.compute();
        results.add(root);
        for (int i = 0; i < root.getChildCount(); i++) {
            processSequentially(root.getChild(i), results);
        }
    }

    static void processInParallel(ExecutorService exec, Node root, List<Node> results) throws InterruptedException {
        if (root == null) {
            return;
        }
        final List<Node> safeResults = Collections.synchronizedList(results);
        submitTree(exec, root, safeResults);
    }

    private static CountDownLatch submitTree(ExecutorService exec, Node root, List<Node> results) {
        List<Node> collected = new ArrayList<Node>();
        int total = countNodes(root, collected);
        final CountDownLatch latch = new CountDownLatch(total);
        for (final Node node : collected) {
            exec.execute(() -> {
                try {
                    node.compute();
                    results.add(node);
                } finally {
                    latch.countDown();
                }
            });
        }
        try {
            latch.await();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        return latch;
    }

    private static int countNodes(Node root, List<Node> collected) {
        if (root == null) {
            return 0;
        }
        collected.add(root);
        int count = 1;
        for (int i = 0; i < root.getChildCount(); i++) {
            count += countNodes(root.getChild(i), collected);
        }
        return count;
    }

    static class SimpleNode implements Node {
        private final String name;
        private final List<Node> children = new ArrayList<Node>();

        SimpleNode(String name) {
            this.name = name;
        }

        void addChild(SimpleNode child) {
            children.add(child);
        }

        @Override
        public Node getChild(int i) {
            return children.get(i);
        }

        @Override
        public int getChildCount() {
            return children.size();
        }

        @Override
        public void compute() {
            System.out.println("Computed node " + name + " on " + Thread.currentThread().getName());
        }
    }

    public static void main(String[] args) throws InterruptedException {
        SimpleNode root = new SimpleNode("root");
        SimpleNode child1 = new SimpleNode("child1");
        SimpleNode child2 = new SimpleNode("child2");
        root.addChild(child1);
        root.addChild(child2);

        ExecutorService exec = Executors.newFixedThreadPool(2);
        try {
            List<Node> results = new ArrayList<Node>();
            processInParallel(exec, root, results);
            System.out.println("Parallel results count: " + results.size());
        } finally {
            exec.shutdown();
        }
    }
}

import java.util.concurrent.atomic.AtomicLong;

public class LockOrderingTransfer {

    interface DollarAmount {
        long getCents();

        DollarAmount add(DollarAmount other);

        DollarAmount subtract(DollarAmount other);

        boolean isLessThan(DollarAmount other);
    }

    static class SimpleDollarAmount implements DollarAmount {
        private final long cents;

        SimpleDollarAmount(long cents) {
            this.cents = cents;
        }

        @Override
        public long getCents() {
            return cents;
        }

        @Override
        public DollarAmount add(DollarAmount other) {
            return new SimpleDollarAmount(this.cents + other.getCents());
        }

        @Override
        public DollarAmount subtract(DollarAmount other) {
            return new SimpleDollarAmount(this.cents - other.getCents());
        }

        @Override
        public boolean isLessThan(DollarAmount other) {
            return this.cents < other.getCents();
        }

        @Override
        public String toString() {
            return "$" + (cents / 100.0);
        }
    }

    interface Account {
        DollarAmount getBalance();

        void setBalance(DollarAmount balance);
    }

    static class SimpleAccount implements Account {
        private DollarAmount balance;

        SimpleAccount(DollarAmount balance) {
            this.balance = balance;
        }

        @Override
        public synchronized DollarAmount getBalance() {
            return balance;
        }

        @Override
        public synchronized void setBalance(DollarAmount balance) {
            this.balance = balance;
        }
    }

    static class InsufficientFundsException extends Exception {
        InsufficientFundsException(String message) {
            super(message);
        }
    }

    private static final Object tieBreakingLock = new Object();

    static void transferMoney(final Account fromAcct, final Account toAcct, final DollarAmount amount)
            throws InsufficientFundsException {
        class Helper {
            void transfer() throws InsufficientFundsException {
                if (fromAcct.getBalance().isLessThan(amount)) {
                    throw new InsufficientFundsException("Insufficient funds");
                }
                fromAcct.setBalance(fromAcct.getBalance().subtract(amount));
                toAcct.setBalance(toAcct.getBalance().add(amount));
            }
        }

        int fromHash = System.identityHashCode(fromAcct);
        int toHash = System.identityHashCode(toAcct);

        if (fromHash < toHash) {
            synchronized (fromAcct) {
                synchronized (toAcct) {
                    new Helper().transfer();
                }
            }
        } else if (fromHash > toHash) {
            synchronized (toAcct) {
                synchronized (fromAcct) {
                    new Helper().transfer();
                }
            }
        } else {
            synchronized (tieBreakingLock) {
                synchronized (fromAcct) {
                    synchronized (toAcct) {
                        new Helper().transfer();
                    }
                }
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
        final Account accountA = new SimpleAccount(new SimpleDollarAmount(10000));
        final Account accountB = new SimpleAccount(new SimpleDollarAmount(5000));

        Runnable transferAtoB = () -> {
            try {
                transferMoney(accountA, accountB, new SimpleDollarAmount(1000));
            } catch (InsufficientFundsException e) {
                System.out.println("Transfer A->B failed: " + e.getMessage());
            }
        };

        Runnable transferBtoA = () -> {
            try {
                transferMoney(accountB, accountA, new SimpleDollarAmount(500));
            } catch (InsufficientFundsException e) {
                System.out.println("Transfer B->A failed: " + e.getMessage());
            }
        };

        Thread t1 = new Thread(transferAtoB, "transfer-a-to-b");
        Thread t2 = new Thread(transferBtoA, "transfer-b-to-a");

        t1.start();
        t2.start();
        t1.join();
        t2.join();

        System.out.println("Account A balance: " + accountA.getBalance());
        System.out.println("Account B balance: " + accountB.getBalance());
    }
}

