public class StripedMap {
    private static final int N_LOCKS = 16;
    private final Node[] buckets;
    private final Object[] locks;

    public StripedMap(int numBuckets) {
        buckets = new Node[numBuckets];
        locks = new Object[N_LOCKS];
        for (int i = 0; i < N_LOCKS; i++) {
            locks[i] = new Object();
        }
    }

    private static class Node {
        final Object key;
        volatile Object value;
        Node next;

        Node(Object key, Object value, Node next) {
            this.key = key;
            this.value = value;
            this.next = next;
        }
    }

    private int hash(Object key) {
        return Math.abs(key.hashCode() % buckets.length);
    }

    public Object get(Object key) {
        int hash = hash(key);
        synchronized (locks[hash % N_LOCKS]) {
            for (Node m = buckets[hash]; m != null; m = m.next) {
                if (m.key.equals(key)) {
                    return m.value;
                }
            }
        }
        return null;
    }

    public void put(Object key, Object value) {
        int hash = hash(key);
        synchronized (locks[hash % N_LOCKS]) {
            for (Node m = buckets[hash]; m != null; m = m.next) {
                if (m.key.equals(key)) {
                    m.value = value;
                    return;
                }
            }
            buckets[hash] = new Node(key, value, buckets[hash]);
        }
    }

    public void clear() {
        for (int i = 0; i < buckets.length; i++) {
            synchronized (locks[i % N_LOCKS]) {
                buckets[i] = null;
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
        final StripedMap map = new StripedMap(64);

        Runnable writer = () -> {
            for (int i = 0; i < 100; i++) {
                map.put("key-" + i, i);
            }
        };

        Runnable reader = () -> {
            for (int i = 0; i < 100; i++) {
                map.get("key-" + i);
            }
        };

        Thread t1 = new Thread(writer, "writer-1");
        Thread t2 = new Thread(writer, "writer-2");
        Thread t3 = new Thread(reader, "reader-1");
        Thread t4 = new Thread(reader, "reader-2");

        t1.start();
        t2.start();
        t3.start();
        t4.start();
        t1.join();
        t2.join();
        t3.join();
        t4.join();

        System.out.println("key-5 value: " + map.get("key-5"));
        map.clear();
        System.out.println("After clear, key-5 value: " + map.get("key-5"));
    }
}

import java.util.concurrent.Semaphore;

public class BoundedBufferSemaphore<E> {
    private final Object[] items;
    private int putIndex, takeIndex;
    private final Semaphore availableItems;
    private final Semaphore availableSpaces;

    public BoundedBufferSemaphore(int capacity) {
        items = new Object[capacity];
        availableItems = new Semaphore(0);
        availableSpaces = new Semaphore(capacity);
    }

    public boolean isEmpty() {
        return availableItems.availablePermits() == 0;
    }

    public boolean isFull() {
        return availableSpaces.availablePermits() == 0;
    }

    public void put(E x) throws InterruptedException {
        availableSpaces.acquire();
        doInsert(x);
        availableItems.release();
    }

    @SuppressWarnings("unchecked")
    public E take() throws InterruptedException {
        availableItems.acquire();
        E item = doExtract();
        availableSpaces.release();
        return item;
    }

    private synchronized void doInsert(E x) {
        int i = putIndex;
        items[i] = x;
        putIndex = (++putIndex == items.length) ? 0 : putIndex;
    }

    @SuppressWarnings("unchecked")
    private synchronized E doExtract() {
        int i = takeIndex;
        E x = (E) items[i];
        items[i] = null;
        takeIndex = (++takeIndex == items.length) ? 0 : takeIndex;
        return x;
    }

    public static void main(String[] args) throws InterruptedException {
        final BoundedBufferSemaphore<Integer> buffer = new BoundedBufferSemaphore<Integer>(5);

        Thread producer = new Thread(() -> {
            try {
                for (int i = 0; i < 10; i++) {
                    buffer.put(i);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }, "producer-thread");

        Thread consumer = new Thread(() -> {
            try {
                for (int i = 0; i < 10; i++) {
                    Integer value = buffer.take();
                    System.out.println("Consumed: " + value);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }, "consumer-thread");

        producer.start();
        consumer.start();
        producer.join();
        consumer.join();
    }
}

import java.util.Random;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.ReentrantLock;

public class TryLockDeadlockAvoidance {

    static class DollarAmount {
        private final long cents;

        DollarAmount(long cents) {
            this.cents = cents;
        }

        long getCents() {
            return cents;
        }

        DollarAmount add(DollarAmount other) {
            return new DollarAmount(this.cents + other.cents);
        }

        DollarAmount subtract(DollarAmount other) {
            return new DollarAmount(this.cents - other.cents);
        }

        boolean isLessThan(DollarAmount other) {
            return this.cents < other.cents;
        }

        @Override
        public String toString() {
            return "$" + (cents / 100.0);
        }
    }

    static class Account {
        private final ReentrantLock lock = new ReentrantLock();
        private DollarAmount balance;

        Account(DollarAmount balance) {
            this.balance = balance;
        }

        ReentrantLock getLock() {
            return lock;
        }

        DollarAmount getBalance() {
            return balance;
        }

        void debit(DollarAmount amount) {
            balance = balance.subtract(amount);
        }

        void credit(DollarAmount amount) {
            balance = balance.add(amount);
        }
    }

    static class InsufficientFundsException extends Exception {
        InsufficientFundsException(String message) {
            super(message);
        }
    }

    private static final Random rnd = new Random();

    private static long fixedDelay() {
        return 10L;
    }

    private static long randomDelay() {
        return rnd.nextInt(10);
    }

    public static boolean transferMoney(final Account fromAcct, final Account toAcct, final DollarAmount amount,
            long timeout, TimeUnit unit) throws InsufficientFundsException, InterruptedException {
        long fixedDelay = fixedDelay();
        long randMod = randomDelay();
        long stopTime = System.nanoTime() + unit.toNanos(timeout);

        while (true) {
            if (fromAcct.getLock().tryLock()) {
                try {
                    if (toAcct.getLock().tryLock()) {
                        try {
                            if (fromAcct.getBalance().isLessThan(amount)) {
                                throw new InsufficientFundsException("Insufficient funds");
                            }
                            fromAcct.debit(amount);
                            toAcct.credit(amount);
                            return true;
                        } finally {
                            toAcct.getLock().unlock();
                        }
                    }
                } finally {
                    fromAcct.getLock().unlock();
                }
            }

            if (System.nanoTime() >= stopTime) {
                return false;
            }

            try {
                Thread.sleep(fixedDelay + randMod);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                throw e;
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
        final Account accountA = new Account(new DollarAmount(10000));
        final Account accountB = new Account(new DollarAmount(5000));

        Runnable transferAtoB = () -> {
            try {
                boolean success = transferMoney(accountA, accountB, new DollarAmount(1000), 1, TimeUnit.SECONDS);
                System.out.println("A->B transfer success: " + success);
            } catch (InsufficientFundsException e) {
                System.out.println("A->B failed: " + e.getMessage());
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        };

        Runnable transferBtoA = () -> {
            try {
                boolean success = transferMoney(accountB, accountA, new DollarAmount(500), 1, TimeUnit.SECONDS);
                System.out.println("B->A transfer success: " + success);
            } catch (InsufficientFundsException e) {
                System.out.println("B->A failed: " + e.getMessage());
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        };

        Thread t1 = new Thread(transferAtoB, "transfer-a-to-b");
        Thread t2 = new Thread(transferBtoA, "transfer-b-to-a");

        t1.start();
        t2.start();
        t1.join();
        t2.join();

        System.out.println("Final A: " + accountA.getBalance());
        System.out.println("Final B: " + accountB.getBalance());
    }
}

import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.locks.ReadWriteLock;
import java.util.concurrent.locks.ReentrantReadWriteLock;

public class ReadWriteMap<K, V> {
    private final Map<K, V> map;
    private final ReadWriteLock lock = new ReentrantReadWriteLock();

    public ReadWriteMap(Map<K, V> map) {
        this.map = map;
    }

    public V put(K key, V value) {
        lock.writeLock().lock();
        try {
            return map.put(key, value);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public V remove(Object key) {
        lock.writeLock().lock();
        try {
            return map.remove(key);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public void putAll(Map<? extends K, ? extends V> m) {
        lock.writeLock().lock();
        try {
            map.putAll(m);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public void clear() {
        lock.writeLock().lock();
        try {
            map.clear();
        } finally {
            lock.writeLock().unlock();
        }
    }

    public V get(Object key) {
        lock.readLock().lock();
        try {
            return map.get(key);
        } finally {
            lock.readLock().unlock();
        }
    }

    public int size() {
        lock.readLock().lock();
        try {
            return map.size();
        } finally {
            lock.readLock().unlock();
        }
    }

    public boolean isEmpty() {
        lock.readLock().lock();
        try {
            return map.isEmpty();
        } finally {
            lock.readLock().unlock();
        }
    }

    public boolean containsKey(Object key) {
        lock.readLock().lock();
        try {
            return map.containsKey(key);
        } finally {
            lock.readLock().unlock();
        }
    }

    public boolean containsValue(Object value) {
        lock.readLock().lock();
        try {
            return map.containsValue(value);
        } finally {
            lock.readLock().unlock();
        }
    }

    public static void main(String[] args) throws InterruptedException {
        final ReadWriteMap<String, Integer> map = new ReadWriteMap<String, Integer>(new HashMap<String, Integer>());

        Thread writer = new Thread(() -> {
            for (int i = 0; i < 10; i++) {
                map.put("key-" + i, i);
            }
        }, "writer-thread");

        Thread reader1 = new Thread(() -> {
            for (int i = 0; i < 10; i++) {
                map.get("key-" + i);
            }
        }, "reader-thread-1");

        Thread reader2 = new Thread(() -> {
            for (int i = 0; i < 10; i++) {
                map.containsKey("key-" + i);
            }
        }, "reader-thread-2");

        writer.start();
        writer.join();

        reader1.start();
        reader2.start();
        reader1.join();
        reader2.join();

        System.out.println("Map size: " + map.size());
    }
}

public class SimulatedCAS {
    private int value;

    public SimulatedCAS(int value) {
        this.value = value;
    }

    public synchronized int get() {
        return value;
    }

    public synchronized int compareAndSwap(int expectedValue, int newValue) {
        int oldValue = value;
        if (oldValue == expectedValue) {
            value = newValue;
        }
        return oldValue;
    }

    public synchronized boolean compareAndSet(int expectedValue, int newValue) {
        return compareAndSwap(expectedValue, newValue) == expectedValue;
    }

    public static void main(String[] args) throws InterruptedException {
        final SimulatedCAS cas = new SimulatedCAS(0);

        Thread updater = new Thread(() -> {
            boolean success = cas.compareAndSet(0, 42);
            System.out.println("Update success: " + success + ", value: " + cas.get());
        }, "updater-thread");

        updater.start();
        updater.join();

        System.out.println("Final value: " + cas.get());
    }
}

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;

public class TreiberStack<E> {
    private final AtomicReference<Node<E>> top = new AtomicReference<Node<E>>();

    private static class Node<E> {
        final E item;
        Node<E> next;

        Node(E item) {
            this.item = item;
        }
    }

    public void push(E item) {
        Node<E> newHead = new Node<E>(item);
        Node<E> oldHead;
        do {
            oldHead = top.get();
            newHead.next = oldHead;
        } while (!top.compareAndSet(oldHead, newHead));
    }

    public E pop() {
        Node<E> oldHead;
        Node<E> newHead;
        do {
            oldHead = top.get();
            if (oldHead == null) {
                return null;
            }
            newHead = oldHead.next;
        } while (!top.compareAndSet(oldHead, newHead));
        return oldHead.item;
    }

    public static void main(String[] args) throws InterruptedException {
        final TreiberStack<Integer> stack = new TreiberStack<Integer>();
        ExecutorService executor = Executors.newFixedThreadPool(3);

        Runnable task = () -> {
            String name = Thread.currentThread().getName();
            for (int i = 0; i < 5; i++) {
                stack.push(i);
                System.out.println(name + " pushed " + i);
            }
            for (int i = 0; i < 5; i++) {
                Integer value = stack.pop();
                System.out.println(name + " popped " + value);
            }
        };

        executor.execute(task);
        executor.execute(task);
        executor.execute(task);

        executor.shutdown();
        executor.awaitTermination(10, TimeUnit.SECONDS);

        System.out.println("All tasks completed.");
    }
}

public class LazyInitialization {

