public class MonitorCounter {
    private long value = 0;

    public synchronized long getValue() {
        return value;
    }

    public synchronized long increment() {
        if (value == Long.MAX_VALUE) {
            throw new IllegalStateException("counter overflow");
        }
        return ++value;
    }

    public static void main(String[] args) throws InterruptedException {
        final MonitorCounter counter = new MonitorCounter();

        Runnable task = () -> {
            for (int i = 0; i < 1000; i++) {
                counter.increment();
            }
        };

        Thread t1 = new Thread(task, "thread-1");
        Thread t2 = new Thread(task, "thread-2");

        t1.start();
        t2.start();
        t1.join();
        t2.join();

        System.out.println("Final counter value: " + counter.getValue());
    }
}

import java.util.HashMap;
import java.util.Map;

public class MonitorVehicleTracker {

    static class MutablePoint {
        int x;
        int y;

        MutablePoint(int x, int y) {
            this.x = x;
            this.y = y;
        }

        MutablePoint(MutablePoint p) {
            this.x = p.x;
            this.y = p.y;
        }

        @Override
        public String toString() {
            return "(" + x + ", " + y + ")";
        }
    }

    private final Map<String, MutablePoint> locations;

    public MonitorVehicleTracker(Map<String, MutablePoint> locations) {
        this.locations = deepCopy(locations);
    }

    public synchronized Map<String, MutablePoint> getLocations() {
        return deepCopy(locations);
    }

    public synchronized MutablePoint getLocation(String id) {
        MutablePoint point = locations.get(id);
        return point == null ? null : new MutablePoint(point);
    }

    public synchronized void setLocation(String id, int x, int y) {
        MutablePoint point = locations.get(id);
        if (point == null) {
            throw new IllegalArgumentException("No such vehicle: " + id);
        }
        point.x = x;
        point.y = y;
    }

    private static Map<String, MutablePoint> deepCopy(Map<String, MutablePoint> source) {
        Map<String, MutablePoint> copy = new HashMap<String, MutablePoint>();
        for (Map.Entry<String, MutablePoint> entry : source.entrySet()) {
            copy.put(entry.getKey(), new MutablePoint(entry.getValue()));
        }
        return copy;
    }

    public static void main(String[] args) throws InterruptedException {
        Map<String, MutablePoint> initial = new HashMap<String, MutablePoint>();
        initial.put("car1", new MutablePoint(0, 0));
        initial.put("car2", new MutablePoint(1, 1));

        final MonitorVehicleTracker tracker = new MonitorVehicleTracker(initial);

        Thread updater = new Thread(() -> tracker.setLocation("car1", 5, 5), "updater-thread");
        updater.start();
        updater.join();

        System.out.println("Locations: " + tracker.getLocations());
        System.out.println("car1: " + tracker.getLocation("car1"));
    }
}

import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Semaphore;
import java.util.concurrent.TimeUnit;

public class BoundedHashSet<T> {
    private final Set<T> set;
    private final Semaphore sem;

    public BoundedHashSet(int bound) {
        this.set = Collections.synchronizedSet(new HashSet<T>());
        this.sem = new Semaphore(bound);
    }

    public boolean add(T o) throws InterruptedException {
        sem.acquire();
        boolean wasAdded = false;
        try {
            wasAdded = set.add(o);
            return wasAdded;
        } finally {
            if (!wasAdded) {
                sem.release();
            }
        }
    }

    public boolean remove(Object o) {
        boolean wasRemoved = set.remove(o);
        if (wasRemoved) {
            sem.release();
        }
        return wasRemoved;
    }

    public static void main(String[] args) throws InterruptedException {
        final BoundedHashSet<Integer> boundedSet = new BoundedHashSet<Integer>(3);
        ExecutorService executor = Executors.newFixedThreadPool(4);

        for (int i = 0; i < 4; i++) {
            final int value = i;
            executor.execute(() -> {
                try {
                    boolean added = boundedSet.add(value);
                    System.out.println(Thread.currentThread().getName() + " added " + value + ": " + added);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            });
        }

        executor.shutdown();
        executor.awaitTermination(5, TimeUnit.SECONDS);

        System.out.println("Set contents: " + boundedSet.set);
    }
}

