import java.util.concurrent.atomic.AtomicInteger;
import java.util.logging.Level;
import java.util.logging.Logger;

public class MyAppThreadLifecycle extends Thread {
    public static final String DEFAULT_NAME = "MyAppThread";

    private static final Logger logger = Logger.getLogger(MyAppThreadLifecycle.class.getName());
    private static final AtomicInteger nameCounter = new AtomicInteger();
    private static final AtomicInteger created = new AtomicInteger();
    private static final AtomicInteger alive = new AtomicInteger();

    private static volatile boolean debugLifecycle = false;

    public MyAppThreadLifecycle(Runnable runnable) {
        this(runnable, DEFAULT_NAME + "-" + nameCounter.incrementAndGet());
    }

    public MyAppThreadLifecycle(Runnable runnable, String name) {
        super(runnable, name);
        setUncaughtExceptionHandler((t, e) -> logger.log(Level.SEVERE, "Uncaught exception in thread " + t.getName(), e));
        created.incrementAndGet();
    }

    @Override
    public void run() {
        boolean debug = debugLifecycle;
        if (debug) {
            logger.log(Level.FINE, "Created " + getName());
        }
        try {
            alive.incrementAndGet();
            super.run();
        } finally {
            alive.decrementAndGet();
            if (debug) {
                logger.log(Level.FINE, "Exiting " + getName());
            }
        }
    }

    public static int getCreated() {
        return created.get();
    }

    public static int getAlive() {
        return alive.get();
    }

    public static void setDebug(boolean b) {
        debugLifecycle = b;
    }

    public static void main(String[] args) throws InterruptedException {
        MyAppThreadLifecycle.setDebug(true);

        Runnable task = () -> {
            for (int i = 0; i < 1000; i++) {
                Math.sqrt(i);
            }
        };

        MyAppThreadLifecycle t1 = new MyAppThreadLifecycle(task);
        MyAppThreadLifecycle t2 = new MyAppThreadLifecycle(task);

        t1.start();
        t2.start();
        t1.join();
        t2.join();

        System.out.println("Created: " + MyAppThreadLifecycle.getCreated());
        System.out.println("Alive: " + MyAppThreadLifecycle.getAlive());
    }
}

import java.util.Random;

public class DemonstrateDeadlock {
    private static final int NUM_THREADS = 2;
    private static final int NUM_ACCOUNTS = 5;
    private static final int NUM_ITERATIONS = 10;

    static class DollarAmount {
        private final long cents;

        DollarAmount(long cents) {
            this.cents = cents;
        }

        long getCents() {
            return cents;
        }

        DollarAmount add(DollarAmount other) {
            return new DollarAmount(this.cents + other.cents);
        }

        DollarAmount subtract(DollarAmount other) {
            return new DollarAmount(this.cents - other.cents);
        }

        boolean isLessThan(DollarAmount other) {
            return this.cents < other.cents;
        }
    }

    static class Account {
        private DollarAmount balance;

        Account(DollarAmount balance) {
            this.balance = balance;
        }

        synchronized DollarAmount getBalance() {
            return balance;
        }

        synchronized void debit(DollarAmount amount) {
            balance = balance.subtract(amount);
        }

        synchronized void credit(DollarAmount amount) {
            balance = balance.add(amount);
        }
    }

    static class InsufficientFundsException extends Exception {
    }

    static class DynamicOrderDeadlock {
        private static final Object tieLock = new Object();

        static void transferMoney(final Account fromAcct, final Account toAcct, final DollarAmount amount)
                throws InsufficientFundsException {
            int fromHash = System.identityHashCode(fromAcct);
            int toHash = System.identityHashCode(toAcct);

            if (fromHash < toHash) {
                synchronized (fromAcct) {
                    synchronized (toAcct) {
                        doTransfer(fromAcct, toAcct, amount);
                    }
                }
            } else if (fromHash > toHash) {
                synchronized (toAcct) {
                    synchronized (fromAcct) {
                        doTransfer(fromAcct, toAcct, amount);
                    }
                }
            } else {
                synchronized (tieLock) {
                    synchronized (fromAcct) {
                        synchronized (toAcct) {
                            doTransfer(fromAcct, toAcct, amount);
                        }
                    }
                }
            }
        }

        private static void doTransfer(Account fromAcct, Account toAcct, DollarAmount amount)
                throws InsufficientFundsException {
            if (fromAcct.getBalance().isLessThan(amount)) {
                throw new InsufficientFundsException();
            }
            fromAcct.debit(amount);
            toAcct.credit(amount);
        }
    }

    static class TransferThread extends Thread {
        private final Account[] accounts;
        private final Random random = new Random();

        TransferThread(Account[] accounts) {
            this.accounts = accounts;
        }

        @Override
        public void run() {
            for (int i = 0; i < NUM_ITERATIONS; i++) {
                int fromIndex = random.nextInt(accounts.length);
                int toIndex = random.nextInt(accounts.length);
                if (fromIndex == toIndex) {
                    continue;
                }
                DollarAmount amount = new DollarAmount(random.nextInt(1000));
                try {
                    DynamicOrderDeadlock.transferMoney(accounts[fromIndex], accounts[toIndex], amount);
                } catch (InsufficientFundsException ignored) {
                    // ignored, as specified
                }
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
        Account[] accounts = new Account[NUM_ACCOUNTS];
        for (int i = 0; i < NUM_ACCOUNTS; i++) {
            accounts[i] = new Account(new DollarAmount(100000));
        }

        Thread[] threads = new Thread[NUM_THREADS];
        for (int i = 0; i < NUM_THREADS; i++) {
            threads[i] = new TransferThread(accounts);
        }

        for (Thread t : threads) {
            t.start();
        }
        for (Thread t : threads) {
            t.join();
        }

        System.out.println("All transfers completed.");
    }
}

