public class BarrierTimer implements Runnable {
    private boolean started;
    private long startTime;
    private long endTime;

    @Override
    public synchronized void run() {
        long t = System.nanoTime();
        if (!started) {
            started = true;
            startTime = t;
        } else {
            endTime = t;
        }
    }

    public synchronized void clear() {
        started = false;
    }

    public synchronized long getTime() {
        return endTime - startTime;
    }

    public static void main(String[] args) throws InterruptedException {
        final BarrierTimer timer = new BarrierTimer();

        Thread startThread = new Thread(timer, "start-thread");
        startThread.start();
        startThread.join();

        Thread.sleep(50);

        Thread endThread = new Thread(timer, "end-thread");
        endThread.start();
        endThread.join();

        System.out.println("Elapsed time (ns): " + timer.getTime());
    }
}

public class CasCounter {

    static class SimulatedCAS {
        private int value;

        synchronized int get() {
            return value;
        }

        synchronized int compareAndSwap(int expected, int newValue) {
            int oldValue = value;
            if (oldValue == expected) {
                value = newValue;
            }
            return oldValue;
        }
    }

    private final SimulatedCAS value = new SimulatedCAS();

    public int getValue() {
        return value.get();
    }

    public int increment() {
        int v;
        do {
            v = value.get();
        } while (v != value.compareAndSwap(v, v + 1));
        return v + 1;
    }

    public static void main(String[] args) throws InterruptedException {
        final CasCounter counter = new CasCounter();

        Runnable task = () -> {
            for (int i = 0; i < 1000; i++) {
                counter.increment();
            }
        };

        Thread t1 = new Thread(task, "thread-1");
        Thread t2 = new Thread(task, "thread-2");

        t1.start();
        t2.start();
        t1.join();
        t2.join();

        System.out.println("Final counter value: " + counter.getValue());
    }
}
